package com.gamemesh.ai.model.dto;

import com.gamemesh.ai.model.enums.SentimentScore;
import com.gamemesh.ai.model.enums.SeverityLevel;

/**
 * Structured digest output generated by the Spring AI autonomous agent.
 */
public record CommunityDigest(
        String headline,
        String summary,
        SeverityLevel severity,
        SentimentScore sentiment,
        Double performanceImpactScore,
        String recommendedAction
) {
    public static CommunityDigest fallback(String headline, String summary, SeverityLevel severity, SentimentScore sentiment) {
        return new CommunityDigest(headline, summary, severity, sentiment, 0.1, "Log for monitoring");
    }
}

